/**
 * dsh-mcp-manager — 中间层（工作空间 MCP 路由）。
 *
 * 模型面恒定两个工具（ws_mcp_search / ws_mcp_call），执行时按调用方会话
 * 当前 cwd（agent.session.header.cwd，实证已闭合）路由到对应工作空间的
 * MCP 连接池，实现「不同工作空间注入不同 MCP、无命名冲突」：
 * - 连接池：每工作空间一套常驻连接（惰性连接 + 超时 + LRU 淘汰）；
 * - 目录：每工作空间 ToolCatalog（惰性发现 + last-good 磁盘缓存 + 检索）；
 * - 策略：server/tool 两级 glob（deny 优先），按 @root/server 全名配置；
 * - 容错：normalizeToolName / normalizeArguments / msgOf / createRedactor。
 *
 * 双轨迁移：middleware 配置为 "off"（默认直呼）/ "project"（项目级走中间层，
 * 全局 mcp__ 直呼）/ "all"（全部走中间层）。
 *
 * 阶段 6 集中搬移：本文件归 connection/runtime/（中间层池），仅保留
 * McpMiddleware 类；原汇聚转发块删除（v3 §二：汇聚只留 src/index.ts）。
 */

import { mkdir, readFile, rename, writeFile, rm } from "node:fs/promises";
import { existsSync } from "node:fs";
import { dirname } from "node:path";
import type { ServerConfig } from "../../types/interface.ts";
import type { ToolDefinition, ToolOutputDefinition } from "@deepseek-ai/dsh-tools";
import { MCPClient } from "./protocol.ts";
import { defaultCallResultFallbackText, projectCallToolResult, withTimeout, msgOf, createRedactor, normalizeArguments } from "../../pipeline/interface.ts";
import { resolveReconnect } from "../interface.ts";
import { createTransport } from "./transport.ts";
import {
  CONNECT_TIMEOUT_MS,
  DISCOVERY_TIMEOUT_MS,
  CALL_TIMEOUT_MS,
  CATALOG_TTL_MS,
} from "./limits.ts";
import {
  parseFullServerName,
  normalizeToolName,
  fullServerName,
  bareServerName,
  MIDDLEWARE_GLOBAL_ROOT,
} from "../../workspace/interface.ts";
import { policyAllows, policyDenialReason, isToolDenied, toolDisabledReason } from "../../pipeline/interface.ts";
import { isCatalogFresh, boundCatalogTools } from "../../catalog/interface.ts";
import type {
  MiddlewareHost,
  ProjectUnit,
  MiddlewarePolicy,
  ConnectionEntry,
  CatalogTool,
  DisabledToolsMap,
} from "../../types/interface.ts";



// ------------------------------------------------------------ 连接池

/**
 * 中间层：工作空间 MCP 连接池 + 目录 + 路由执行。
 * 一个实例服务所有工作空间（projectUnits: Map<root, ProjectUnit>）。
 */
export class McpMiddleware {
  host: MiddlewareHost;
  /** root（realpath 归一化）→ 工作空间单元。 */
  units: Map<string, ProjectUnit>;
  /** 策略（按 @root/server 全名配置）。 */
  policy: MiddlewarePolicy;
  /** 用户禁用映射（root → Set<server>），单元创建时合并。 */
  disabledByRoot: Map<string, Set<string>> = new Map();
  /** 工具级禁用（root → server → Set<tool>；root=@global 跨工作空间共享）。 */
  disabledTools: DisabledToolsMap = new Map();

  constructor(host: MiddlewareHost, policy: MiddlewarePolicy = {}) {
    this.host = host;
    this.units = new Map();
    this.policy = policy;
  }

  /** 读取/创建 root 的单元（root 无项目标记 → undefined）。 */
  async projectUnitFor(root: string | undefined): Promise<ProjectUnit | undefined> {
    if (root === undefined) return undefined;
    let unit = this.units.get(root);
    if (unit === undefined) {
      const servers = await this.host.projectServersFor(root);
      if (servers === undefined) return undefined;
      unit = {
        root,
        connections: new Map(),
        catalog: new Map(),
        userDisabled: new Set(this.disabledByRoot.get(root) ?? []),
        lastTouchedAt: Date.now(),
        inFlight: new Map(),
      };
      this.units.set(root, unit);
      // 加载 last-good 目录缓存（空采集不写盘；目录与连接分开淘汰）。
      await this.loadCatalogCache(root);
      // 后台惰性连接（fire-and-forget，不阻塞调用方）。
      for (const server of servers) {
        if (server.enabled !== false) void this.ensureConnected(root, server.name);
      }
    }
    unit.lastTouchedAt = Date.now();
    return unit;
  }

  /** 连接一个服务器（in-flight 去重；失败后台重连）。
   * @param opts.force 用户显式连接（浮窗「连接」/切回前台恢复）时 true：忽略
   *  entry 当前状态（含半开卡在 connected 的死连接），总是受控重建；惰性/重试
   *  路径缺省 false，保持「已 connected 则短路」防重复建连。
   */
  async ensureConnected(root: string, serverName: string, opts: { force?: boolean } = {}): Promise<void> {
    const unit = this.units.get(root);
    if (unit === undefined) return;
    if (unit.userDisabled.has(serverName)) return;
    const servers = await this.host.projectServersFor(root);
    const server = servers?.find((entry) => entry.name === serverName);
    if (server === undefined || server.enabled === false) return;
    const existing = unit.inFlight.get(serverName);
    if (existing !== undefined) return existing as Promise<void>;
    const promise = this.connectInternal(root, serverName, opts);
    unit.inFlight.set(serverName, promise);
    try {
      await promise;
    } finally {
      // 所有权校验：仅当标记仍指向本次 attempt 才清除。强制拆除（abandonInFlight）
      // 后同名可能已挂上新 attempt——被废弃的旧 attempt 迟到收敛时不得误删新标记
      // （误删窗口内第三次 ensureConnected 会绕过去重）。
      if (unit.inFlight.get(serverName) === promise) unit.inFlight.delete(serverName);
    }
  }

  /** 废弃某服务器跨全部单元的在途建连标记。
   *  不变式：in-flight 去重只对「存活 entry 的重复建连」有意义——entry 被强制
   *  拆除（remove/update/disconnect）时，同名旧 attempt 可能仍 pending（connect
   *  挂至 CONNECT_TIMEOUT_MS 才超时；stdio close 打断时 SDK 不 reject），残留
   *  标记会把后续 ensureConnected（含 force 的用户显式「连接」）全部吞掉，且旧
   *  attempt 收敛时命中 disposed 守卫静默返回、无人补连 → 服务器最长 10s 内
   *  无法重连。拆除时必须同步废弃标记；旧 attempt 稍后收敛由 connectInternal
   *  的让位/disposed 守卫兜底，无副作用。 */
  abandonInFlight(serverName: string): void {
    for (const unit of this.units.values()) unit.inFlight.delete(serverName);
  }

  private async connectInternal(root: string, serverName: string, opts: { force?: boolean } = {}): Promise<void> {
    const unit = this.units.get(root);
    if (unit === undefined) return;
    const force = opts.force === true;
    const entry = unit.connections.get(serverName);
    // 非 force：已 connected/connecting 短路，防重复建连。
    // force（用户显式「连接」/切回前台恢复）：忽略当前状态，总是受控重建——
    // 修半开死连接卡在 connected 后 connect/refresh 均短路失效（#412）。
    if (!force && entry !== undefined && (entry.status === "connected" || entry.status === "connecting")) return;
    // 重连路径：旧 entry（failed，或 force 重建的死连接）的 transport 先 close，
    // 防 streamable-http 半开 socket 累积泄漏（P1 修复）。
    if (entry !== undefined) {
      const oldClient = entry.client;
      const oldTransport = entry.transport;
      entry.client = undefined;
      entry.transport = undefined;
      if (oldClient !== undefined && oldTransport !== undefined) {
        void oldTransport.close().catch(() => {});
      }
    }
    const servers = await this.host.projectServersFor(root);
    const server = servers?.find((entry) => entry.name === serverName);
    if (server === undefined || server.enabled === false) return;
    // #413：封装定义服务器（runtime 注入 toolDefinitions）——
    // execute 为调用方 JS 直呼 CLI，不经远端 MCP callTool，**不 spawn transport**。
    // 中间层以「虚拟连接」（无 client/transport，status=connected）+ 目录从
    // toolDefinitions 投影存在；执行走 callTool 的封装直呼分支。
    // 判定用 Array.isArray（空数组也算封装声明——调用方显式声明无工具，
    // 不应回退远端 spawn）。
    if (Array.isArray(server.toolDefinitions)) {
      const existingWrapped = unit.connections.get(serverName);
      if (existingWrapped !== undefined && (existingWrapped.status === "connected" || existingWrapped.status === "connecting")) return;
      const wrappedEntry: ConnectionEntry = {
        server,
        client: undefined,
        transport: undefined,
        status: "connected",
        error: undefined,
        connectedAt: Date.now(),
        reconnectTimer: undefined,
        disposed: false,
        failedAttempts: 0,
      };
      unit.connections.set(serverName, wrappedEntry);
      this.projectWrappedCatalog(root, serverName, server);
      this.host.logger.info(`dsh-mcp-manager(${serverName}@${root}): wrapped (toolDefinitions) connected`);
      this.host.emitStatus();
      return;
    }
    // 与官方 dsh-mcp-client 并存（方案 E2）：运行时探测官方/其他插件是否已注册
    // 同名 server 的 mcp__ 工具（说明该 server 已有其他实例连接）→ 跳过本实例，
    // 防同一 server 双进程。探测失败（tools.schemas 不可用）不阻塞连接。
    if (this.host.ctx.tools !== undefined && typeof this.host.ctx.tools.schemas === "function") {
      try {
        const registered = this.host.ctx.tools.schemas();
        const prefix = `mcp__${serverName}__`;
        if (Array.isArray(registered) && registered.some((schema) => typeof schema?.name === "string" && (schema.name as string).startsWith(prefix))) {
          this.host.logger.warn(`dsh-mcp-manager(${serverName}@${root}): server 已由其他插件（如官方 dsh-mcp-client）注册 mcp__ 工具，跳过本实例连接（防双进程）`);
          // F5（#382）：命中多为热更新/模式切换窗口期——旧实例 mcp__ 注册尚未
          // 注销（dispose 为 fire-and-forget）。确保存在可挂重试定时器的 entry
          // （首次连接无旧 entry → 落 failed 占位；旧 entry 保留其退避语义），
          // 安排一次有界延迟重试，避免窗口期「一次定终身」掉线；重试经
          // ensureConnected（尊重 userDisabled + in-flight 去重），再命中仍跳过
          // （官方 client 真接管场景不空转）。
          // #412 force 重建：复用旧 entry 可能是 connected 死连接，必须置
          // failed——否则 probeRetry 3s 后 ensureConnected（无 force）对
          // connected 短路，重试永不执行（死循环）。
          const retryEntry = unit.connections.get(serverName) ?? {
            server,
            client: undefined,
            transport: undefined,
            status: "failed",
            error: undefined,
            connectedAt: undefined,
            reconnectTimer: undefined,
            disposed: false,
            failedAttempts: 0,
          };
          retryEntry.status = "failed";
          retryEntry.client = undefined;
          retryEntry.transport = undefined;
          unit.connections.set(serverName, retryEntry);
          this.scheduleProbeRetry(root, serverName);
          return;
        }
      } catch {
        // 探测失败不阻塞
      }
    }
    // 让位校验：本次 attempt 期间（上方 await 窗口内）entry 已被强制拆除并由
    // 更新的 attempt 重建（abandonInFlight 语义）——在 spawn 前退避：既防旧配置
    // 的 entry 覆盖新 entry，也不遗孤 transport（退避点在 createTransport 之前）。
    const current = unit.connections.get(serverName);
    if (current !== undefined && current !== entry) return;
    const transport = createTransport(server);
    const client = new MCPClient(transport);
    const newEntry: ConnectionEntry = {
      server,
      client,
      transport,
      status: "connecting",
      error: undefined,
      connectedAt: undefined,
      reconnectTimer: undefined,
      disposed: false,
      failedAttempts: entry?.failedAttempts ?? 0,
      probeRetried: entry?.probeRetried ?? false,
    };
    unit.connections.set(serverName, newEntry);
    const closeHandler = (error: Error) => {
      if (newEntry.disposed) return;
      if (unit.connections.get(serverName) !== newEntry) return;
      // B4/B18：状态投影交给 scheduleReconnect 统一裁决（预算内 reconnecting /
      // 耗尽 failed）——closeHandler 只记账（failedAttempts）与排重连。
      newEntry.error = error;
      newEntry.connectedAt = undefined;
      // B18：连上后断开同样计入 failedAttempts——否则退避恒 initialDelay（500ms
      // 抖动），与「从未连上」的失败路径退避口径分裂。
      newEntry.failedAttempts += 1;
      this.scheduleReconnect(root, serverName);
    };
    if ("onClose" in transport && transport.onClose !== undefined) transport.onClose(closeHandler);
    try {
      await withTimeout(transport.connect(), CONNECT_TIMEOUT_MS, `connect timed out (${CONNECT_TIMEOUT_MS}ms)`);
      await withTimeout(client.initialize(), CONNECT_TIMEOUT_MS, `initialize timed out (${CONNECT_TIMEOUT_MS}ms)`);
      await this.discover(root, serverName);
      if (newEntry.disposed || unit.connections.get(serverName) !== newEntry) return;
      newEntry.status = "connected";
      newEntry.connectedAt = Date.now();
      newEntry.failedAttempts = 0;
      newEntry.probeRetried = false;
      this.host.logger.info(`dsh-mcp-manager(${serverName}@${root}): connected`);
      this.host.emitStatus();
    } catch (error) {
      if (newEntry.disposed || unit.connections.get(serverName) !== newEntry) return;
      this.host.logger.warn(`dsh-mcp-manager(${serverName}@${root}): connection attempt failed: ${this.redact(error)}`);
      // B4/B18：状态投影交给 scheduleReconnect 统一裁决（预算内 reconnecting /
      // 耗尽 failed）——catch 只记账（failedAttempts）与排重连。
      newEntry.error = error;
      newEntry.failedAttempts += 1;
      this.scheduleReconnect(root, serverName);
    }
  }

  /**
   * 后台重连（有界指数退避：initialDelay 起、maxDelay 上限、maxAttempts 次后停止
   * 后台重试；用户手动 connect 或 ws_mcp_call 触发时重新尝试——常驻语义）。
   * 退避/预算从 connection/runtime 单一解析函数取（与 supervisor resolveReconnect
   * 同口径，B18）；状态投影：预算内 reconnecting（B4，客户端 counts.reconnecting /
   * summarize 分级依赖此态）、预算耗尽或 reconnect.enabled=false → failed。
   */
  private scheduleReconnect(root: string, serverName: string): void {
    const unit = this.units.get(root);
    if (unit === undefined) return;
    const entry = unit.connections.get(serverName);
    if (entry === undefined || entry.disposed) return;
    if (entry.reconnectTimer !== undefined) return;
    // B18：解析走 connection/runtime 单一事实源（现状内联 500/30000/10 且忽略
    // enabled 字段，与 supervisor resolveReconnect 口径分裂）。
    const policy = resolveReconnect(entry.server?.reconnect);
    if (!policy.enabled) {
      // B18：reconnect.enabled=false → 不安排后台重试（保持 failed 状态）。
      entry.status = "failed";
      this.host.emitStatus();
      return;
    }
    if (entry.failedAttempts > policy.maxAttempts) {
      // 预算耗尽：停止后台重试（保持 failed 状态；手动/调用触发可再试）。
      entry.status = "failed";
      this.host.emitStatus();
      this.host.logger.warn(`dsh-mcp-manager(${serverName}@${root}): reconnect gave up after ${policy.maxAttempts} attempts`);
      return;
    }
    // B4：退避窗口内状态投影为 reconnecting（区别于预算耗尽的 failed）。
    entry.status = "reconnecting";
    this.host.emitStatus();
    const delayMs = Math.min(policy.maxDelayMs, policy.initialDelayMs * 2 ** Math.min(entry.failedAttempts - 1, 6));
    entry.reconnectTimer = setTimeout(() => {
      entry.reconnectTimer = undefined;
      if (entry.disposed) return;
      void this.connectInternal(root, serverName);
    }, delayMs);
    entry.reconnectTimer.unref?.();
  }

  /**
   * 防双进程探测命中后的一次性有界重试（#382 F5）。定时器复用 entry.reconnectTimer
   * 槽位（teardownUnit/disconnect 路径统一清理）；重试经 ensureConnected——它
   * 查 userDisabled + in-flight 去重，不会复活用户已断开的服务器、不与手动重连
   * 并发冲突。每代 entry 只重试一次（probeRetried 标记；连接成功复位），官方
   * dsh-mcp-client 真接管时不会反复空转。
   */
  private scheduleProbeRetry(root: string, serverName: string): void {
    const unit = this.units.get(root);
    if (unit === undefined) return;
    const entry = unit.connections.get(serverName);
    if (entry === undefined || entry.disposed) return;
    if (entry.reconnectTimer !== undefined) return;
    if (entry.probeRetried === true) return;
    entry.probeRetried = true;
    const PROBE_RETRY_DELAY_MS = 3000;
    entry.reconnectTimer = setTimeout(() => {
      entry.reconnectTimer = undefined;
      if (entry.disposed) return;
      void this.ensureConnected(root, serverName);
    }, PROBE_RETRY_DELAY_MS);
    entry.reconnectTimer.unref?.();
  }

  /** 发现工具并写入目录（per-root in-flight 去重）。 */
  async discover(root: string, serverName: string): Promise<void> {
    const unit = this.units.get(root);
    if (unit === undefined) return;
    const entry = unit.connections.get(serverName);
    if (entry === undefined || entry.client === undefined) return;
    if (isCatalogFresh(unit.catalog.get(serverName))) return; // fresh
    try {
      const tools = await withTimeout(this.listToolsAll(entry.client), DISCOVERY_TIMEOUT_MS, `discovery timed out (${DISCOVERY_TIMEOUT_MS}ms)`);
      unit.catalog.set(serverName, { discoveredAt: Date.now(), tools: boundCatalogTools(tools) });
      this.persistCatalog(root);
    } catch (error) {
      unit.catalog.set(serverName, { discoveredAt: 0, tools: new Map(), unavailable: this.redact(error) });
    }
  }

  /**
   * #413：从封装定义（toolDefinitions）投影目录，替代远端 discover。
   * 封装 execute 为调用方 JS 直呼（不经远端 MCP），目录数据源即调用方定义：
   * name/description 直取；dsh-tools 的 parameters（ToolSchema）即 JSON Schema
   * 形态，直接作 CatalogTool.inputSchema（与 supervisor 封装分支同口径）。
   */
  private projectWrappedCatalog(root: string, serverName: string, server: ServerConfig): void {
    const unit = this.units.get(root);
    if (unit === undefined) return;
    const tools = new Map<string, CatalogTool>();
    if (Array.isArray(server.toolDefinitions)) {
      for (const def of server.toolDefinitions) {
        if (typeof def?.name !== "string" || def.name === "") continue;
        tools.set(def.name, {
          description: typeof def.description === "string" ? def.description : "",
          inputSchema: (def.parameters ?? {}) as Record<string, unknown>,
        });
      }
    }
    unit.catalog.set(serverName, { discoveredAt: Date.now(), tools });
  }

  /** 凭据脱敏（连接/发现/调用错误路径统一使用；P1 修复）。 */
  private redact(error: unknown): string {
    return createRedactor(this.allServers())(error);
  }

  private async listToolsAll(client: MCPClient): Promise<Array<Record<string, unknown>>> {
    const all: Array<Record<string, unknown>> = [];
    let cursor: string | undefined;
    do {
      const response = (await client.listTools(cursor)) as { tools?: unknown[]; nextCursor?: unknown } | undefined;
      const tools = response?.tools ?? [];
      for (const tool of tools) {
        if (typeof tool === "object" && tool !== null) all.push(tool as Record<string, unknown>);
      }
      cursor = response?.nextCursor as string | undefined;
    } while (cursor !== undefined && cursor !== null && cursor !== "");
    return all;
  }

  /** 目录 last-good 持久化（空采集不写盘；public 供测试与外部触发）。 */
  async persistCatalog(root: string): Promise<void> {
    const unit = this.units.get(root);
    if (unit === undefined) return;
    let anyTools = false;
    const payload: Record<string, unknown> = {};
    for (const [serverName, catalog] of unit.catalog) {
      // #413：runtime 注入条目（内存态，不落盘）目录只驻内存——防卸载/重启后
      // 幽灵条目被 loadCatalogCache 载回（与 removeCatalogEntry 清理同类问题）。
      if (this.host.isRuntimeServer?.(serverName) === true) continue;
      if (catalog.tools.size === 0) continue;
      anyTools = true;
      payload[serverName] = {
        discoveredAt: catalog.discoveredAt,
        tools: [...catalog.tools.entries()].map(([name, tool]) => ({ name, description: tool.description, inputSchema: tool.inputSchema })),
      };
    }
    if (!anyTools) return;
    const file = this.host.catalogCachePath(root);
    try {
      const dir = dirname(file);
      if (!existsSync(dir)) await mkdir(dir, { recursive: true });
      const tmp = `${file}.${process.pid}.${Date.now().toString(36)}.tmp`;
      await writeFile(tmp, JSON.stringify({ version: 1, root, entries: payload }, null, 2), "utf8");
      await rename(tmp, file);
    } catch (error) {
      this.host.logger.warn(`dsh-mcp-manager: catalog cache write failed: ${msgOf(error)}`);
    }
  }

  /**
   * 从磁盘 last-good 目录缓存中清除单服务器条目（remove/update 后调用；#392 遗留①）。
   * persistCatalog 是全量覆盖且空采集不写盘——remove 后该 root 目录可能已空，若不显式
   * 清盘，磁盘缓存仍残留已删服务器条目，插件重启/@global 单元重建时 loadCatalogCache
   * 把幽灵条目载回（ws_mcp_list 再次列出）。这里读现有缓存、删条目、写回；条目删空则
   * 删除缓存文件。内存目录由调用方（dropMiddlewareConnection）先行删除。
   */
  async removeCatalogEntry(root: string, serverName: string): Promise<void> {
    const file = this.host.catalogCachePath(root);
    try {
      if (!existsSync(file)) return;
      const raw = await readFile(file, "utf8");
      const parsed = JSON.parse(raw) as { version?: unknown; root?: unknown; entries?: Record<string, unknown> } | null;
      if (parsed === null || typeof parsed !== "object" || typeof parsed.entries !== "object" || parsed.entries === null) return;
      if (!(serverName in parsed.entries)) return;
      delete parsed.entries[serverName];
      if (Object.keys(parsed.entries).length === 0) {
        await rm(file, { force: true }).catch(() => {});
        return;
      }
      const tmp = `${file}.${process.pid}.${Date.now().toString(36)}.tmp`;
      await writeFile(tmp, JSON.stringify({ version: 1, root, entries: parsed.entries }, null, 2), "utf8");
      await rename(tmp, file);
    } catch (error) {
      this.host.logger.warn(`dsh-mcp-manager: catalog cache remove failed: ${msgOf(error)}`);
    }
  }

  /** 加载 root 的 last-good 目录缓存（缺失/损坏 → 空）。 */
  async loadCatalogCache(root: string): Promise<void> {
    const unit = this.units.get(root);
    if (unit === undefined) return;
    const file = this.host.catalogCachePath(root);
    try {
      if (!existsSync(file)) return;
      const raw = await readFile(file, "utf8");
      const parsed = JSON.parse(raw) as { entries?: Record<string, unknown> } | null;
      if (parsed && typeof parsed === "object" && typeof parsed.entries === "object" && parsed.entries !== null) {
        for (const [serverName, entry] of Object.entries(parsed.entries)) {
          const rec = entry as { discoveredAt?: unknown; tools?: unknown } | undefined;
          if (typeof rec !== "object" || rec === null) continue;
          const tools = new Map<string, CatalogTool>();
          if (Array.isArray(rec.tools)) {
            for (const tool of rec.tools) {
              const toolRec = tool as { name?: unknown; description?: unknown; inputSchema?: unknown } | undefined;
              if (typeof toolRec !== "object" || toolRec === null || typeof toolRec.name !== "string") continue;
              tools.set(toolRec.name, {
                description: typeof toolRec.description === "string" ? toolRec.description : "",
                inputSchema: (toolRec.inputSchema ?? {}) as Record<string, unknown>,
              });
            }
          }
          unit.catalog.set(serverName, {
            discoveredAt: typeof rec.discoveredAt === "number" ? rec.discoveredAt : 0,
            tools,
          });
        }
      }
    } catch {
      // 损坏缓存忽略
    }
  }

  /** 执行 ws_mcp_call：路由 + 一致性校验 + 策略 + 调用。
   * @param agent 调用方会话 agent（透传给封装定义的 execute，供 session cwd
   *   解析；#413 封装直呼分支需要）。 */
  async callTool(
    fullName: string,
    toolRaw: string,
    rawArgs: unknown,
    signal: AbortSignal | undefined,
    agent?: unknown,
  ): Promise<unknown> {
    const parsed = parseFullServerName(fullName);
    if (parsed === undefined) {
      throw new Error(`ws_mcp_call: unknown server ${JSON.stringify(fullName)}; 格式应为 @<root>/<server>`);
    }
    const unit = this.units.get(parsed.root);
    if (unit === undefined) {
      throw new Error(`ws_mcp_call: 工作空间 ${JSON.stringify(parsed.root)} 未激活；请先 ws_mcp_search 或 ws_mcp_list`);
    }
    const entry = unit.connections.get(parsed.server);
    const entryStatus = entry?.status;
    // B4 连带：六态状态机补 reconnecting 后，调用守卫须把「后台重连中」纳入未就绪
    // 范畴——否则退避窗口内会落到下方 entry.client.callTool（client 未 initialize）。
    if (entry === undefined || entryStatus === "failed" || entryStatus === "reconnecting" || entryStatus === "stopped" || entryStatus === "disabled") {
      if (unit.userDisabled.has(parsed.server)) {
        throw new Error(`ws_mcp_call: server ${JSON.stringify(fullName)} 已被用户禁用；可先在 GUI「MCP」浮窗中重新连接`);
      }
      if (entryStatus === "reconnecting") {
        throw new Error(`ws_mcp_call: server ${JSON.stringify(fullName)} 连接失败、正在后台重连；请稍后重试或重新连接`);
      }
      throw new Error(`ws_mcp_call: server ${JSON.stringify(fullName)} 未连接或连接失败，请先 ws_mcp_search 或 ws_mcp_list 确认 server 已连接`);
    }
    if (entryStatus === "connecting") {
      throw new Error(`ws_mcp_call: server ${JSON.stringify(fullName)} 连接仍在进行，请稍后重试；连接完成后再调用`);
    }
    const tool = normalizeToolName(parsed.server, toolRaw);
    // 工具级禁用（先查禁用表再查策略；P0-1 三入口统一走 isToolDenied）。
    const policyKey = fullServerName(parsed.root, parsed.server);
    if (isToolDenied(this.disabledTools, this.policy, policyKey, tool)) {
      // 策略拒绝与禁用拒绝文案区分（策略拒绝附「调整 middlewarePolicy 配置」下一步）。
      if (!policyAllows(this.policy, policyKey, tool)) {
        const reason = policyDenialReason(this.policy, policyKey, tool);
        throw new Error(`${reason ?? `ws_mcp_call: 工具 ${JSON.stringify(`${policyKey}/${tool}`)} 被策略拒绝`}；如需放行请调整 middlewarePolicy 配置`);
      }
      throw new Error(toolDisabledReason(policyKey, tool));
    }
    const catalog = unit.catalog.get(parsed.server);
    const stale =
      catalog !== undefined && catalog.unavailable === undefined && Date.now() - catalog.discoveredAt > CATALOG_TTL_MS;
    if (stale) {
      // stale：仍可调用（目录只是提示），但 schema 可能过期——在结果前置提示。
    }
    const args = normalizeArguments(rawArgs);
    // B18/D6：调用预算读 server.toolCallTimeoutMs（缺省 CALL_TIMEOUT_MS），
    // withTimeout 兜底统一 +2s——两路径（supervisor SDK timeoutMs 无兜底）预算
    // 差异写入两路径契约测试的差异面签名。
    const callBudgetMs = entry.server?.toolCallTimeoutMs ?? CALL_TIMEOUT_MS;
    // #413 封装直呼分支：runtime 注入的封装定义服务器（toolDefinitions）——
    // execute 为调用方 JS（不经远端 client.callTool）。禁用/策略已在上面统一
    // 裁决（isToolDenied），此处直接调调用方 execute；输出经封装 output.render
    // 投影为 ContentBlock[]（与 supervisor 封装分支 / dsh-tools 同口径）。
    const wrapped = entry.server?.toolDefinitions;
    if (Array.isArray(wrapped)) {
      const def = wrapped.find((d) => d?.name === tool);
      if (def === undefined) {
        throw new Error(`ws_mcp_call: 工具 ${JSON.stringify(`${parsed.server}/${tool}`)} 不存在（封装定义服务器）`);
      }
      try {
        // 封装定义契约：execute(args, exec) 的 exec 为完整 ToolRunContext，但
        // 中间层只能提供最小面（agent 透传，session cwd 解析用）——经 unknown
        // 中转（消费方封装定义只读 exec.agent）。
        const execCtx = { agent } as unknown as Parameters<NonNullable<ToolDefinition["execute"]>>[1];
        // #413 QA P2-2：封装 execute 补超时兜底（与远端分支同预算 callBudgetMs，
        // 封装实现挂起时不无限等待）。
        const value = await withTimeout(
          def.execute(
            typeof args === "object" && args !== null ? args : {},
            execCtx,
          ),
          callBudgetMs + 2000,
          `ws_mcp_call: 封装调用超时（${callBudgetMs}ms），可重试；若反复超时请检查插件状态`,
          signal,
        );
        const content = typeof def.output?.render === "function"
          ? def.output.render(args, value as unknown as Parameters<NonNullable<ToolOutputDefinition["render"]>>[1])
          : [{ type: "text", text: typeof value === "string" ? value : JSON.stringify(value ?? {}) }];
        // #512 共性问题：structuredContent 条件展开——封装 execute 返回 undefined
        // 时不落键，防显式 undefined 值键触发宿主 lossless JSON 校验失败（#381 同源）。
        return {
          content,
          ...(value !== undefined ? { structuredContent: value } : {}),
        };
      } catch (error) {
        if (signal?.aborted === true) throw signal.reason;
        throw new Error(this.hostRedact(`ws_mcp_call: ${JSON.stringify(`${parsed.server}/${tool}`)} 封装调用失败：${msgOf(error)}`));
      }
    }
    if (entry.client === undefined) {
      throw new Error(`ws_mcp_call: server ${JSON.stringify(fullName)} 未就绪（client 缺失）；请稍后重试或重新连接`);
    }
    try {
      const result = await withTimeout(
        entry.client.callTool(tool, typeof args === "object" && args !== null ? args : {}, {
          signal,
          timeoutMs: callBudgetMs,
        }),
        callBudgetMs + 2000,
        `ws_mcp_call: 调用超时（${callBudgetMs}ms），可重试；若反复超时请用 ws_mcp_detail 核对参数或检查服务器状态`,
        signal,
      );
      // #512：远端结果经 call-result.ts 统一投影收敛（isError 判定 + 白名单
      // 清洗 + 无 content 兜底），与 supervisor（mcp__ 直呼）/ 官方
      // dsh-mcp-client createExecutor 同一契约——不再裸透传 resultObj，
      // Python SDK 必带的 isError:false / _meta 等字段不再外泄进工具契约。
      // fallbackText（复核闸 F1）：content 键存在但非数组（协议违规形态）时
      // 保留远端原文（msgOf，与旧文案行为等价）；content 缺省走默认兜底。
      const projected = projectCallToolResult(result, {
        errorText: (content) =>
          `ws_mcp_call: 远端工具返回错误：${msgOf(content)}；可先用 ws_mcp_detail 核对参数 schema 后重试`,
        fallbackText: (r) => {
          const raw = typeof r === "object" && r !== null && "content" in r ? (r as { content?: unknown }).content : undefined;
          return raw !== undefined && !Array.isArray(raw) ? msgOf(raw) : defaultCallResultFallbackText(r);
        },
      });
      if (stale) {
        // schema 可能已过期：结果前置提示（投影后的白名单结构，仅扩 content）。
        const hint = { type: "text", text: "（提示：本工具目录已过期，schema 可能已变更，请重新 ws_mcp_search）" };
        return {
          content: [hint, ...projected.content],
          ...(projected.structuredContent !== undefined ? { structuredContent: projected.structuredContent } : {}),
        };
      }
      return projected;
    } catch (error) {
      if (signal?.aborted === true) throw signal.reason;
      throw new Error(this.hostRedact(`ws_mcp_call: ${JSON.stringify(`${parsed.server}/${tool}`)} 调用失败：${msgOf(error)}`));
    }
  }

  private hostRedact(text: string): string {
    const redactor = createRedactor([...this.allServers()]);
    return redactor(new Error(text));
  }

  private allServers(): ServerConfig[] {
    const servers: ServerConfig[] = [];
    for (const unit of this.units.values()) {
      for (const entry of unit.connections.values()) servers.push(entry.server);
    }
    return servers;
  }

  /** LRU 淘汰：无活动引用（lastTouchedAt 最旧）且超过上限时淘汰最旧单元。
   * @global 单元豁免（#382 F3）：全局服务器常连语义不随多项目切换被淘汰
   * （supervisor 时代全局永不淘汰，池接管后需显式豁免保持等价语义）。 */
  evictIfNeeded(maxUnits = 16): void {
    while (this.units.size > maxUnits) {
      let oldestKey: string | undefined;
      let oldestAt = Infinity;
      for (const [root, unit] of this.units) {
        if (root === MIDDLEWARE_GLOBAL_ROOT) continue;
        if (unit.lastTouchedAt < oldestAt) {
          oldestAt = unit.lastTouchedAt;
          oldestKey = root;
        }
      }
      if (oldestKey === undefined) break;
      this.teardownUnit(oldestKey);
    }
  }

  /** 拆毁一个单元（断开全部连接，保留目录缓存）。 */
  teardownUnit(root: string): void {
    const unit = this.units.get(root);
    if (unit === undefined) return;
    for (const entry of unit.connections.values()) {
      entry.disposed = true;
      if (entry.reconnectTimer !== undefined) clearTimeout(entry.reconnectTimer);
      const client = entry.client;
      entry.client = undefined;
      entry.transport = undefined;
      if (client !== undefined && client.transport !== undefined) {
        void client.transport.close().catch(() => {});
      }
    }
    unit.connections.clear();
    this.units.delete(root);
  }

  /** 全部拆毁（插件卸载）。 */
  async dispose(): Promise<void> {
    for (const root of [...this.units.keys()]) this.teardownUnit(root);
    this.units.clear();
  }
}

packages/dsh-mcp-manager/src/inject/midd.source:
/**
 * dsh-mcp-manager — 中间层工具注册（ws_mcp_search / ws_mcp_call /
 * ws_mcp_list / ws_mcp_detail + 策略 guard）。
 *
 * 注册四个中间层工具与策略 guard 层；类型自 middleware-types.ts 取，
 * 连接池类（McpMiddleware）自 middleware.ts import type（防运行值环）。
 * all 模式全局可见性（评审 A）：search/list/detail 合并查询「项目 root 单元 +
 * @global 单元」；call 放行 @global root。off/project 模式行为不变。
 */

import type { Context } from "@deepseek-ai/cordis";
import type { ToolDefinition, PreToolDecision } from "@deepseek-ai/dsh-tools";
import type { McpMiddleware } from "../connection/runtime/interface.ts";
import {
  CONNECT_TIMEOUT_MS,
  DISCOVERY_TIMEOUT_MS,
  CALL_TIMEOUT_MS,
  LIST_DEFAULT_TOOLS_PER_SERVER,
  LIST_MAX_TOOLS_PER_SERVER,
} from "../connection/runtime/interface.ts";
import { withTimeout } from "../pipeline/interface.ts";
import { policyAllows, policyDenialReason, isToolDenied, toolDisabledReason } from "../pipeline/interface.ts";
import { searchCatalogMulti, listCatalog, findToolDetail } from "../catalog/interface.ts";
import { parseFullServerName, fullServerName, MIDDLEWARE_GLOBAL_ROOT } from "../workspace/interface.ts";
import type { MiddlewareMode, DisabledToolsMap } from "../types/interface.ts";
import type { McpStatsCollector } from "../stats/interface.ts";

/** 工具执行与组装上下文。 */
interface MiddlewareToolContext {
  mw: McpMiddleware;
  resolveRoot: (agent: unknown) => Promise<string | undefined>;
  mode: MiddlewareMode;
  stats?: McpStatsCollector;
}

/** 空 query 搜索无命中时的可归因提示（纯 render 文案，C 项）。 */
const SEARCH_EMPTY_HINT =
  "(No matching MCP tools found in current workspace; use ws_mcp_list for full inventory or verify server/tool names before searching)";

/** 项目级可见服务器名列表（A1 归因文案用；排序去重）。 */
function visibleProjectServers(mw: McpMiddleware, root: string): string[] {
  const names: string[] = [];
  for (const unit of mw.units.values()) {
    if (unit.root === root) {
      for (const serverName of unit.catalog.keys()) names.push(serverName);
    }
  }
  return [...new Set(names)].sort();
}

/** 等待 in-flight 连接/发现（8s 预算，与 search 对齐；超时不阻塞返回已有目录）。 */
async function waitForDiscovery(unit: NonNullable<Awaited<ReturnType<McpMiddleware["projectUnitFor"]>>>): Promise<void> {
  const inflight = [...unit.inFlight.values()];
  if (inflight.length === 0) return;
  try {
    await withTimeout(Promise.allSettled(inflight), 8000, "等待连接/发现超时");
  } catch {
    // 超时不阻塞（返回已有目录）
  }
}

/**
 * all 模式可见单元集合：项目 root + @global（评审 A 全局可见性修复）。
 * root 本身为 @global 时去重（防 all 模式无项目 cwd 下服务器翻倍）。
 */
function visibleMiddlewareRoots(root: string | undefined, mode: MiddlewareMode): string[] {
  if (root === undefined) return [];
  if (mode !== "all") return [root];
  return root === "@global" ? ["@global"] : [root, "@global"];
}

/**
 * 路由一致性校验（detail/call 共用；A2）：目标 root 必须等于当前 root，
 * 或 all 模式下的 @global（全局配置跨工作空间共享，语义成立）。
 * project 模式传全局级服务器 → 引导改用 mcp__ 直呼（全局 mcp__ 工具在该
 * 模式下仍注册可用）；非 global 的其他 root / 未知 @global 服务器一律硬拒绝
 * （防跨空间串台与 project 模式经 @global 路由绕过）。
 * @returns 校验通过的 root；抛错则拒绝。
 */
async function checkMiddlewareRoot(
  caller: string,
  server: string,
  root: string,
  mode: MiddlewareMode,
  mw: McpMiddleware,
): Promise<string | undefined> {
  const parsed = parseFullServerName(server);
  if (parsed === undefined) {
    throw new Error(`${caller}: server 参数格式非法，应为 @<root>/<server>`);
  }
  if (parsed.root !== root && parsed.root !== MIDDLEWARE_GLOBAL_ROOT) {
    throw new Error(
      `${caller}: server ${JSON.stringify(server)} 不属于当前工作空间 ${JSON.stringify(root)}；路由一致性校验失败（防跨空间串台）`,
    );
  }
  if (parsed.root === MIDDLEWARE_GLOBAL_ROOT && mode !== "all") {
    const bare = parsed.server;
    const known = mw.host.isGlobalServer(bare) || mw.units.get(MIDDLEWARE_GLOBAL_ROOT)?.catalog.has(bare) === true;
    if (known) {
      throw new Error(
        `${caller}: server ${JSON.stringify(server)} 是全局级（global scope）服务器，中间层只覆盖项目级服务器；请直接用 mcp__${bare}__<tool> 前缀工具调用（project 模式全局工具仍直呼注册）`,
      );
    }
    throw new Error(
      `${caller}: server ${JSON.stringify(server)} 不属于当前工作空间 ${JSON.stringify(root)}；路由一致性校验失败（防跨空间串台）`,
    );
  }
  return parsed.root;
}

// ---------------------------------------------------------------------------
// 1. ws_mcp_search
// ---------------------------------------------------------------------------

function formatSearchHit(hit: Record<string, unknown>): string {
  const server = String(hit.server ?? "");
  const tool = String(hit.tool ?? "");
  const description = String(hit.description ?? "");
  return `${server}/${tool}: ${description}`;
}

function formatUnavailableServer(entry: Record<string, unknown>): string {
  return `${String(entry.server ?? "")}: ${String(entry.reason ?? "")}`;
}

function renderSearchOutput(_args: unknown, value: unknown) {
  const v = (value ?? {}) as { results?: Array<Record<string, unknown>>; unavailable?: Array<Record<string, unknown>>; truncated?: unknown };
  const lines = (v.results ?? []).map(formatSearchHit);
  let body = lines.length > 0 ? lines.join("\n") : SEARCH_EMPTY_HINT;
  if (v.truncated === true) {
    body += "\n(Results reached limit and may be incomplete — increase limit or use ws_mcp_list for full audit)";
  }
  const unavailable = (v.unavailable ?? []).map(formatUnavailableServer);
  const text = unavailable.length > 0 ? `${body}\n\nUnavailable servers:\n${unavailable.join("\n")}` : body;
  return [{ type: "text" as const, text }];
}

function parseSearchParams(args: unknown): { query: string; serverFilter?: string; limit: number } {
  const params = (typeof args === "object" && args !== null ? args : {}) as Record<string, unknown>;
  const query = typeof params.query === "string" ? params.query : "";
  const serverFilter = typeof params.server === "string" ? params.server : undefined;
  const requested = typeof params.limit === "number" ? Math.floor(params.limit) : 5;
  const limit = Math.max(1, Math.min(requested, 10));
  return { query, serverFilter, limit };
}

async function executeSearch(
  toolCtx: MiddlewareToolContext,
  args: unknown,
  exec: { signal?: AbortSignal; agent?: unknown },
) {
  const root = await toolCtx.resolveRoot(exec.agent);
  if (root === undefined) throw new Error("ws_mcp_search: 无法确定工作空间，请先选择工作区");
  const { query, serverFilter, limit } = parseSearchParams(args);
  if (toolCtx.stats?.isEnabled()) {
    toolCtx.stats.recordSearch(query);
  }
  const roots = visibleMiddlewareRoots(root, toolCtx.mode);
  const unit = await toolCtx.mw.projectUnitFor(root);
  if (unit === undefined) {
    return { results: [], unavailable: [], truncated: false };
  }
  // 等待 in-flight 连接/发现（预算内），再搜索。all 模式对可见全部单元
  // （含 @global 首次触达）都等待——否则全局目录首次为空（P1-3 修复）。
  for (const visible of roots) {
    const visibleUnit = visible === root ? unit : await toolCtx.mw.projectUnitFor(visible);
    if (visibleUnit !== undefined) await waitForDiscovery(visibleUnit);
  }
  const { results, unavailable, truncated } = searchCatalogMulti(toolCtx.mw.units, roots, query, limit);
  // truncated 由检索函数返回截断事实（恰好命中 limit 不误报，B10 修正——
  // 旧实现按过滤前 results.length >= limit 判定，恰恰等于 limit 也误报
  // 「可能未列全」）；serverFilter 过滤在截断判定之后，纯展示层过滤。
  const filtered = serverFilter === undefined ? results : results.filter((hit) => hit.server === serverFilter);
  return { results: filtered, unavailable, truncated };
}

function buildSearchTool(toolCtx: MiddlewareToolContext): ToolDefinition {
  return {
    name: "ws_mcp_search",
    description:
      "Search workspace MCP tools catalog by keyword (matches server, tool, description, and parameter names). Search first, then invoke with ws_mcp_call; use ws_mcp_list for full inventory audits. Empty query returns capability summary.",
    parameters: {
      type: "object",
      properties: {
        query: { type: "string", description: "Search query / keywords; empty returns capability summary" },
        server: { type: "string", description: "Optional: @<root>/<server> full name filter" },
        limit: { type: "number", description: "Max results to return (default 5, max 10)" },
      },
    },
    output: {
      schema: {
        type: "object",
        properties: {
          results: { type: "array", items: {} },
          unavailable: { type: "array", items: {} },
          truncated: { type: "boolean", description: "结果是否因 limit 截断（results 达到 limit 时为 true，提示模型可能未列全）" },
        },
        required: ["results", "unavailable", "truncated"],
        additionalProperties: false,
      },
      render: renderSearchOutput,
    },
    isConcurrencySafe: () => true,
    execute: (args, exec) => executeSearch(toolCtx, args, exec),
  };
}

// ---------------------------------------------------------------------------
// 2. ws_mcp_call
// ---------------------------------------------------------------------------

function formatCallContentBlock(block: unknown): string {
  if (typeof block !== "object" || block === null) {
    return "[unsupported MCP content]";
  }
  const rec = block as Record<string, unknown>;
  if (rec.type === "text" && typeof rec.text === "string") {
    return rec.text;
  }
  if (rec.type === "resource" || rec.type === "resource_link") {
    return "[resource: content discarded]";
  }
  return `[${String(rec.type ?? "unknown")} content]`;
}

function renderCallOutput(_args: unknown, value: unknown) {
  const v = (value ?? {}) as { content?: unknown };
  const content = Array.isArray(v.content) ? v.content : [];
  const parts = content.map(formatCallContentBlock);
  return [{ type: "text" as const, text: parts.length > 0 ? parts.join("\n") : "(MCP tool returned no content)" }];
}

function parseCallParams(args: unknown): { server: string; tool: string; arguments?: unknown } {
  const params = (typeof args === "object" && args !== null ? args : {}) as Record<string, unknown>;
  const server = typeof params.server === "string" ? params.server : "";
  const tool = typeof params.tool === "string" ? params.tool : "";
  return { server, tool, arguments: params.arguments };
}

async function executeCall(
  toolCtx: MiddlewareToolContext,
  args: unknown,
  exec: { signal?: AbortSignal; agent?: unknown },
) {
  const root = await toolCtx.resolveRoot(exec.agent);
  if (root === undefined) throw new Error("ws_mcp_call: 无法确定工作空间，请先选择工作区");
  const { server, tool, arguments: callArguments } = parseCallParams(args);
  if (server === "" || tool === "") throw new Error("ws_mcp_call: server 与 tool 均为必填");
  const parsed = parseFullServerName(server);
  if (parsed === undefined) throw new Error("ws_mcp_call: server 参数格式非法，应为 @<root>/<server>");
  const targetRoot = await checkMiddlewareRoot("ws_mcp_call", server, root, toolCtx.mode, toolCtx.mw);
  if (targetRoot === undefined) {
    throw new Error(`ws_mcp_call: server ${JSON.stringify(server)} 不属于当前工作空间 ${JSON.stringify(root)}；路由一致性校验失败（防跨空间串台）`);
  }
  const unit = await toolCtx.mw.projectUnitFor(targetRoot);
  if (unit === undefined) throw new Error(`ws_mcp_call: 工作空间 ${JSON.stringify(targetRoot)} 无项目级 MCP 配置`);
  await toolCtx.mw.ensureConnected(targetRoot, parsed.server);
  // #413：透传 exec.agent 给 callTool（封装直呼分支的 execute 依赖
  // agent.session.header.cwd 做 projectPath 补全）。
  const startTime = Date.now();
  try {
    const result = await toolCtx.mw.callTool(server, tool, callArguments, exec.signal, exec.agent);
    const durationMs = Date.now() - startTime;
    if (toolCtx.stats?.isEnabled()) {
      toolCtx.stats.recordCall(parsed.server, tool, durationMs, true);
    }
    return result;
  } catch (error) {
    const durationMs = Date.now() - startTime;
    if (toolCtx.stats?.isEnabled()) {
      toolCtx.stats.recordCall(parsed.server, tool, durationMs, false, error instanceof Error ? error.message : String(error));
    }
    throw error;
  }
}

function buildCallTool(toolCtx: MiddlewareToolContext): ToolDefinition {
  return {
    name: "ws_mcp_call",
    description:
      "Invoke an MCP tool in the current workspace (executes on live server). Verify parameter schema with ws_mcp_detail beforehand (can invoke directly if server and tool are known); obtain user consent before write or sensitive operations.",
    parameters: {
      type: "object",
      properties: {
        server: { type: "string", description: "Required: @<root>/<server> full name (from ws_mcp_search / ws_mcp_list)" },
        tool: { type: "string", description: "Required: bare remote tool name (from ws_mcp_search / ws_mcp_list)" },
        arguments: {
          type: "object",
          additionalProperties: true,
          description:
            "Arguments matching inputSchema from ws_mcp_detail (properties/required/enum/description); check with ws_mcp_detail when uncertain",
        },
      },
      required: ["server", "tool"],
    },
    output: {
      schema: {
        type: "object",
        properties: {
          content: { type: "array", items: {} },
          structuredContent: {},
        },
        required: ["content"],
        additionalProperties: false,
      },
      render: renderCallOutput,
    },
    isConcurrencySafe: () => true,
    timeoutMs: CONNECT_TIMEOUT_MS + DISCOVERY_TIMEOUT_MS + CALL_TIMEOUT_MS + 5000,
    execute: (args, exec) => executeCall(toolCtx, args, exec),
  };
}

// ---------------------------------------------------------------------------
// 3. ws_mcp_list
// ---------------------------------------------------------------------------

function formatListTool(t: Record<string, unknown>): string {
  return `  - ${String(t.tool ?? "")}: ${String(t.description ?? "")}`;
}

function formatListServerEntry(entry: Record<string, unknown>): string {
  const server = String(entry.server ?? "");
  const tools = Array.isArray(entry.tools) ? (entry.tools as Array<Record<string, unknown>>) : [];
  const head =
    tools.length > 0
      ? `${server} (${tools.length} tools):\n${tools.map(formatListTool).join("\n")}`
      : `${server} (0 tools)`;
  const disabled = entry.disabled === true ? " [disabled]" : "";
  const unavailable =
    typeof entry.unavailable === "string" && entry.unavailable !== "" ? ` [unavailable: ${entry.unavailable}]` : "";
  const truncated =
    entry.toolsTruncated === true
      ? " [toolsTruncated: tool count reached limit, increase perServerLimit to retry]"
      : "";
  return `${head}${disabled}${unavailable}${truncated}`;
}

function renderListOutput(_args: unknown, value: unknown) {
  const v = (value ?? {}) as {
    workspace?: unknown;
    mode?: unknown;
    servers?: Array<Record<string, unknown>>;
    totalServers?: unknown;
    totalTools?: unknown;
    toolsTruncated?: unknown;
    message?: unknown;
  };
  const servers = v.servers ?? [];
  const lines = servers.map(formatListServerEntry);
  const prefix = `Workspace ${String(v.workspace ?? "")} (mode=${String(v.mode ?? "")}): ${String(v.totalServers ?? 0)} servers / ${String(v.totalTools ?? 0)} tools in total`;
  const body = lines.length > 0 ? lines.join("\n\n") : String(v.message ?? "(No MCP servers found in current workspace)");
  const truncated =
    v.toolsTruncated === true ? "\n(Some server tool lists were truncated; increase perServerLimit if needed)" : "";
  return [{ type: "text" as const, text: `${prefix}\n\n${body}${truncated}` }];
}

function parseListParams(args: unknown): { serverFilter?: string; toolLimit: number } {
  const params = (typeof args === "object" && args !== null ? args : {}) as Record<string, unknown>;
  const serverFilter = typeof params.server === "string" && params.server !== "" ? params.server : undefined;
  const requested =
    typeof params.perServerLimit === "number" ? Math.floor(params.perServerLimit) : LIST_DEFAULT_TOOLS_PER_SERVER;
  const toolLimit = Math.max(1, Math.min(requested, LIST_MAX_TOOLS_PER_SERVER));
  return { serverFilter, toolLimit };
}

function resolveEmptyListMessage(
  serverFilter: string | undefined,
  mw: McpMiddleware,
  root: string,
  mode: MiddlewareMode,
): string {
  if (serverFilter !== undefined) {
    const visible = visibleProjectServers(mw, root);
    const visibleText = visible.length > 0 ? `可见项目级服务器：${visible.join(" / ")}；` : "当前工作空间无已发现的项目级服务器；";
    return `没有匹配 server=${JSON.stringify(serverFilter)} 的项目级服务器。${visibleText}全局级服务器不在此列出，请用 mcp__<server>__<tool> 前缀工具访问`;
  }
  return mode === "all"
    ? "当前工作空间没有可用 MCP 服务器（项目级与全局均未发现；若刚添加配置，请稍后重试）"
    : "当前工作空间没有可用 MCP 服务器（未配置项目级服务器；若刚添加配置，请稍后重试）";
}

async function resolveListWithoutUnit(
  mw: McpMiddleware,
  root: string,
  mode: MiddlewareMode,
  serverFilter: string | undefined,
  toolLimit: number,
) {
  if (mode !== "all") {
    return {
      workspace: root,
      mode,
      servers: [],
      totalServers: 0,
      totalTools: 0,
      toolsTruncated: false,
      message: "当前工作空间没有项目级 MCP 配置（可在 <项目根>/.dsh/mcp.json 添加服务器，或切换工作区）",
    };
  }
  const globalUnit = await mw.projectUnitFor("@global");
  if (globalUnit !== undefined) await waitForDiscovery(globalUnit);
  return listCatalog(
    mw.units,
    ["@global"],
    serverFilter,
    toolLimit,
    mode,
    "当前工作空间没有可用 MCP 服务器（项目级与全局均未发现；若刚添加配置，请稍后重试）",
    mw.disabledTools,
  );
}

async function executeList(
  toolCtx: MiddlewareToolContext,
  args: unknown,
  exec: { signal?: AbortSignal; agent?: unknown },
) {
  const root = await toolCtx.resolveRoot(exec.agent);
  if (root === undefined) throw new Error("ws_mcp_list: 无法确定工作空间，请先选择工作区");
  const { serverFilter, toolLimit } = parseListParams(args);
  if (toolCtx.stats?.isEnabled()) {
    toolCtx.stats.recordList(serverFilter);
  }
  const roots = visibleMiddlewareRoots(root, toolCtx.mode);
  const unit = await toolCtx.mw.projectUnitFor(root);
  if (unit === undefined) {
    return resolveListWithoutUnit(toolCtx.mw, root, toolCtx.mode, serverFilter, toolLimit);
  }
  // 等待 in-flight 连接/发现（预算内），再搜索。all 模式对可见全部单元
  // （含 @global 首次触达）都等待——否则全局目录首次为空（P1-3 修复）。
  for (const visible of roots) {
    const visibleUnit = visible === root ? unit : await toolCtx.mw.projectUnitFor(visible);
    if (visibleUnit !== undefined) await waitForDiscovery(visibleUnit);
  }
  const result = listCatalog(toolCtx.mw.units, roots, serverFilter, toolLimit, toolCtx.mode, "", toolCtx.mw.disabledTools);
  // A1：带 serverFilter 过滤后 0 命中 → message 可归因（不谎报「未配置」）。
  if (result.servers.length === 0) {
    result.message = resolveEmptyListMessage(serverFilter, toolCtx.mw, root, toolCtx.mode);
  }
  return result;
}

function buildListTool(toolCtx: MiddlewareToolContext): ToolDefinition {
  return {
    name: "ws_mcp_list",
    description:
      "List all MCP servers and their complete tool inventories in current workspace (not truncated by search limit). Returns full server names, tool names, and descriptions. Does not return inputSchema (use ws_mcp_detail for full schemas). Includes global servers in all mode.",
    parameters: {
      type: "object",
      properties: {
        server: {
          type: "string",
          description: "Optional: @<root>/<server> full name or bare name filter (error if root is not in current workspace)",
        },
        perServerLimit: {
          type: "number",
          description: `Optional: max tools per server (default ${LIST_DEFAULT_TOOLS_PER_SERVER}, max ${LIST_MAX_TOOLS_PER_SERVER}; sets toolsTruncated=true when exceeded)`,
        },
      },
    },
    output: {
      schema: {
        type: "object",
        properties: {
          workspace: { type: "string" },
          mode: { type: "string" },
          servers: { type: "array", items: {} },
          totalServers: { type: "number" },
          totalTools: { type: "number" },
          toolsTruncated: { type: "boolean" },
          message: { type: "string" },
        },
        required: ["workspace", "mode", "servers", "totalServers", "totalTools", "toolsTruncated"],
        additionalProperties: false,
      },
      render: renderListOutput,
    },
    isConcurrencySafe: () => true,
    execute: (args, exec) => executeList(toolCtx, args, exec),
  };
}

// ---------------------------------------------------------------------------
// 4. ws_mcp_detail
// ---------------------------------------------------------------------------

function renderDetailOutput(_args: unknown, value: unknown) {
  const v = (value ?? {}) as {
    server?: unknown;
    tool?: unknown;
    description?: unknown;
    inputSchema?: unknown;
    fresh?: unknown;
    disabled?: unknown;
  };
  const server = String(v.server ?? "");
  const tool = String(v.tool ?? "");
  const description = typeof v.description === "string" && v.description !== "" ? v.description : "（无描述）";
  const schema = v.inputSchema === undefined ? "{}" : JSON.stringify(v.inputSchema, null, 2);
  const fresh = v.fresh === true ? "fresh" : "stale";
  const disabled = v.disabled === true ? " [disabled]" : "";
  return [{ type: "text" as const, text: `${server}/${tool}（${fresh}${disabled}）：${description}\n\ninputSchema:\n${schema}` }];
}

function parseDetailParams(args: unknown): { server: string; tool: string } {
  const params = (typeof args === "object" && args !== null ? args : {}) as Record<string, unknown>;
  const server = typeof params.server === "string" ? params.server : "";
  const tool = typeof params.tool === "string" ? params.tool : "";
  return { server, tool };
}

async function executeDetail(
  toolCtx: MiddlewareToolContext,
  args: unknown,
  exec: { signal?: AbortSignal; agent?: unknown },
) {
  const root = await toolCtx.resolveRoot(exec.agent);
  if (root === undefined) throw new Error("ws_mcp_detail: 无法确定工作空间，请先选择工作区");
  const { server, tool } = parseDetailParams(args);
  if (server === "" || tool === "") throw new Error("ws_mcp_detail: server 与 tool 均为必填");
  const parsed = parseFullServerName(server);
  if (toolCtx.stats?.isEnabled()) {
    toolCtx.stats.recordDetail(parsed?.server ?? server, tool);
  }
  const targetRoot = await checkMiddlewareRoot("ws_mcp_detail", server, root, toolCtx.mode, toolCtx.mw);
  if (targetRoot === undefined) {
    throw new Error(
      `ws_mcp_detail: server ${JSON.stringify(server)} 不属于当前工作空间 ${JSON.stringify(root)}；路由一致性校验失败（防跨空间串台）`,
    );
  }
  const unit = await toolCtx.mw.projectUnitFor(targetRoot);
  if (unit !== undefined) await waitForDiscovery(unit);
  return findToolDetail(toolCtx.mw.units, targetRoot, server, tool);
}

function buildDetailTool(toolCtx: MiddlewareToolContext): ToolDefinition {
  return {
    name: "ws_mcp_detail",
    description:
      "Query the exact parameter schema (inputSchema: properties/required/enum/description) of a single MCP tool by @<root>/<server> full name and bare tool name. Used before ws_mcp_call. Does not perform keyword search (use ws_mcp_list or ws_mcp_search to find tools).",
    parameters: {
      type: "object",
      properties: {
        server: { type: "string", description: "Required: @<root>/<server> full name (from ws_mcp_list / ws_mcp_search)" },
        tool: { type: "string", description: "Required: bare remote tool name (from ws_mcp_list / ws_mcp_search; supports mcp__<server>__<tool> prefix)" },
      },
      required: ["server", "tool"],
    },
    output: {
      schema: {
        type: "object",
        properties: {
          server: { type: "string" },
          tool: { type: "string" },
          description: { type: "string" },
          inputSchema: {},
          fresh: { type: "boolean" },
          disabled: { type: "boolean" },
        },
        required: ["server", "tool", "description", "inputSchema", "fresh"],
        additionalProperties: false,
      },
      render: renderDetailOutput,
    },
    isConcurrencySafe: () => true,
    execute: (args, exec) => executeDetail(toolCtx, args, exec),
  };
}

// ---------------------------------------------------------------------------
// 5. Pre-execute Guard
// ---------------------------------------------------------------------------

function handleCallGuard(args: unknown, mw: McpMiddleware): PreToolDecision | undefined {
  const { server, tool } = parseCallParams(args);
  const parsed = parseFullServerName(server);
  if (parsed === undefined || parsed.server === "") return undefined;
  const policyKey = fullServerName(parsed.root, parsed.server);
  if (isToolDenied(mw.disabledTools, mw.policy, policyKey, tool)) {
    if (!policyAllows(mw.policy, policyKey, tool)) {
      return { kind: "deny", reason: policyDenialReason(mw.policy, policyKey, tool) ?? "ws_mcp_call: 工具被策略拒绝" };
    }
    return { kind: "deny", reason: toolDisabledReason(policyKey, tool) };
  }
  return undefined;
}

async function handleDirectMcpGuard(
  name: string,
  agent: unknown,
  disabledTools: DisabledToolsMap | undefined,
  resolveRoot: (agent: unknown) => Promise<string | undefined>,
): Promise<PreToolDecision | undefined> {
  const rest = name.slice("mcp__".length);
  const separator = rest.indexOf("__");
  if (separator <= 0) return undefined;
  const server = rest.slice(0, separator);
  const tool = rest.slice(separator + 2);
  if (tool === "") return undefined;
  // B11（D5 定稿，规格化不可逆）：server/tool 名含连续双下划线时，第一个 `__`
  // 分割无法唯一还原 (server, tool)（mcp__my__sv__t 既可能是 server="my"+
  // tool="sv__t"，也可能是 server="my__sv"+tool="t"）——tool 段仍含 `__` 即
  // 存在歧义，按未知 server 处理（不禁用不误禁，放行 next()）。映射表列入
  // 后续增强；不改 publicToolName/INVALID_NAME_CHARS（防冲击官方 mcp__ 契约）。
  if (tool.includes("__")) return undefined;
  const root = await resolveRoot(agent);
  if (root === undefined) {
    // 无法解析会话 root：按最宽可见范围放行（仅 @global 共享记录生效）。
    if (disabledTools?.get(MIDDLEWARE_GLOBAL_ROOT)?.get(server)?.has(tool) === true) {
      return { kind: "deny", reason: toolDisabledReason(`@${MIDDLEWARE_GLOBAL_ROOT}/${server}`, tool) };
    }
    return undefined;
  }
  const serverKey = fullServerName(root, server);
  if (isToolDenied(disabledTools, undefined, serverKey, tool)) {
    return { kind: "deny", reason: toolDisabledReason(serverKey, tool) };
  }
  return undefined;
}

function registerPreExecuteGuard(
  ctx: Context,
  mw: McpMiddleware,
  resolveRoot: (agent: unknown) => Promise<string | undefined>,
): (() => void) | undefined {
  if (typeof ctx.on !== "function") return undefined;
  return ctx.on(
    "tools/pre-execute",
    async (
      exec: { name?: string; arguments?: unknown; agent?: unknown },
      next: () => Promise<PreToolDecision>,
    ): Promise<PreToolDecision> => {
      const name = exec?.name;
      if (typeof name !== "string" || name === "") return next();
      if (name === "ws_mcp_call") {
        const decision = handleCallGuard(exec.arguments, mw);
        if (decision !== undefined) return decision;
        return next();
      }
      if (name.startsWith("mcp__")) {
        const decision = await handleDirectMcpGuard(name, exec.agent, mw.disabledTools, resolveRoot);
        if (decision !== undefined) return decision;
        return next();
      }
      return next();
    },
  );
}

/**
 * D8：独立 mcp__ 直呼守卫（guard 挂载与中间层实例解耦）。
 *
 * off 模式不 initMiddleware（无连接池副作用），pre-execute guard 现状只在
 * registerMiddlewareTools 内注册 → mcp__ 直呼无禁用拦截（「工具级禁用三入口」
 * 实际一入口）。本守卫数据源直查禁用表（只读），独立注册路径，三模式一致；
 * ws_mcp_call 守卫依赖策略/中间层实例，仅 project/all 经 registerMiddlewareTools
 * 注册。B11 反解规格化逻辑与 registerMiddlewareTools 内 guard 同源
 * （handleDirectMcpGuard）。
 */
export function registerDirectMcpGuard(
  ctx: Context,
  disabledTools: DisabledToolsMap | undefined,
  resolveRoot: (agent: unknown) => Promise<string | undefined>,
): (() => void) | undefined {
  if (typeof ctx.on !== "function") return undefined;
  return ctx.on(
    "tools/pre-execute",
    async (
      exec: { name?: string; agent?: unknown },
      next: () => Promise<PreToolDecision>,
    ): Promise<PreToolDecision> => {
      const name = exec?.name;
      if (typeof name !== "string" || name === "" || !name.startsWith("mcp__")) return next();
      const decision = await handleDirectMcpGuard(name, exec.agent, disabledTools, resolveRoot);
      if (decision !== undefined) return decision;
      return next();
    },
  );
}

// ---------------------------------------------------------------------------
// 6. registerMiddlewareTools 入口函数
// ---------------------------------------------------------------------------

/**
 * 注册 ws_mcp_search / ws_mcp_call / ws_mcp_list / ws_mcp_detail 四个中间层工具。
 * @param ctx Cordis 宿主上下文。
 * @param mw 中间层实例。
 * @param resolveRoot 路由：exec.agent → 归一化项目根（agent-less → undefined）。
 * @param mode 中间层模式（all 模式合并查询 @global 单元）。
 * @param options 可选配置（支持传入自定义工具级禁用表）。
 */
export function registerMiddlewareTools(
  ctx: Context,
  mw: McpMiddleware,
  resolveRoot: (agent: unknown) => Promise<string | undefined>,
  mode: MiddlewareMode = "project",
  options: {
    /** 工具级禁用映射（root → server → Set<tool>）；缺省取 mw.disabledTools。 */
    disabledTools?: DisabledToolsMap;
    /** 可选调用统计收集器。 */
    stats?: McpStatsCollector;
  } = {},
): () => void {
  const disposers: Array<() => void> = [];
  // 单一事实源：options 显式传入时同步到 mw（guard 与 callTool 同源，防漂移）。
  const disabledTools = options.disabledTools ?? mw.disabledTools;
  if (options.disabledTools !== undefined) mw.disabledTools = disabledTools;

  const toolCtx: MiddlewareToolContext = { mw, resolveRoot, mode, stats: options.stats };
  const tools = [
    buildSearchTool(toolCtx),
    buildCallTool(toolCtx),
    buildListTool(toolCtx),
    buildDetailTool(toolCtx),
  ];
  for (const tool of tools) {
    disposers.push(ctx.tools.register(tool));
  }

  const guardDispose = registerPreExecuteGuard(ctx, mw, resolveRoot);
  if (guardDispose !== undefined) {
    disposers.push(guardDispose);
  }

  return () => {
    for (const dispose of disposers) dispose();
  };
}

packages/dsh-mcp-manager/src/pipeline/au.source:
/**
 * dsh-mcp-manager — pipeline/authorize：执行授权纯函数（#664 阶段 2 迁入 + 阶段 6 收敛）。
 *
 * globMatch 阶段 2 迁入；策略裁决族（policyAllows / policyDenialReason /
 * isToolDenied / toolDisabledReason）依赖 parseFullServerName /
 * MIDDLEWARE_GLOBAL_ROOT（workspace 域）与 globMatch，阶段 6 自
 * middleware-utils.ts 并入本文件（该文件随后删除）。parseDisabledTools
 * （禁用表三层解析）并入 config/store/middleware-state.ts（状态域）。
 */

import { fullServerName, parseFullServerName, bareServerName, MIDDLEWARE_GLOBAL_ROOT } from "../workspace/interface.ts";
import type { MiddlewarePolicy, DisabledToolsMap } from "../types/interface.ts";

/** 工具名匹配 glob（* 通配）。 */
export function globMatch(pattern: string, name: string): boolean {
  if (pattern === "*") return true;
  if (!pattern.includes("*")) return pattern === name;
  const escaped = pattern.split("*").map((part) => part.replace(/[.+?^${}()|[\]\\]/g, "\\$&")).join(".*");
  return new RegExp(`^${escaped}$`).test(name);
}

// ------------------------------------------------------------ 策略裁决

/** 策略裁决：deny 优先。serverKey 支持全名（@root/server）或裸名——全名优先匹配（工作空间隔离），未命中回落裸名。返回 true = 允许。 */
export function policyAllows(policy: MiddlewarePolicy | undefined, serverKey: string, tool: string): boolean {
  if (policy === undefined) return true;
  const fullDeny = policy.denyTools?.[serverKey];
  if (fullDeny !== undefined && fullDeny.some((pattern) => globMatch(pattern, tool))) return false;
  const deny = policy.denyTools?.[bareServerName(serverKey)];
  if (deny !== undefined && deny.some((pattern) => globMatch(pattern, tool))) return false;
  const fullAllow = policy.allowTools?.[serverKey];
  if (fullAllow !== undefined && fullAllow.length > 0) {
    return fullAllow.some((pattern) => globMatch(pattern, tool));
  }
  const allow = policy.allowTools?.[bareServerName(serverKey)];
  if (allow === undefined || allow.length === 0) return true;
  return allow.some((pattern) => globMatch(pattern, tool));
}

/**
 * 单一裁决：工具是否被用户禁用（工具级禁用，独立于服务器级 enabled）。
 *
 * 三入口统一调用（P0-1）：ws_mcp_call（callTool，先查禁用再查策略）、
 * pre-execute guard（mcp__ 前缀工具）、插件侧自行声明的纪律裸名。
 *
 * 语义（P0-2 方案 A，零耦合）：禁用**只作用于 mcp-manager 管辖的 mcp__ 前缀
 * 工具**；插件侧声明的纪律裸名工具不受影响，由插件自行声明。
 * 禁用原因文案与浮窗 UI 均需同步声明该语义。
 *
 * 判定（P1 三层结构 + P2 超长名）：
 * 1. 目标 root 直接命中 → 查该 root 记录（project 模式按会话 root 隔离）；
 * 2. 未命中且目标 root 非 @global → 回落 @global 共享记录（全局工具跨工作空间
 *    key=@global；对项目 root 的查询是「该 root 无记录」的探测，永不误禁）；
 * 3. 哈希后缀名（>64 字符或含非法字符）不可逆 → 按「未知 server」处理：
 *    不禁用、不误禁（publicToolName 无法反解出 (server, tool)）。
 *
 * @param disabledTools 禁用映射（root → server → Set<tool>）。
 * @param policy 中间层策略（allowTools/denyTools；工具级禁用之外的第二道闸，
 *    仅 ws_mcp_call 路径检查，与既有语义一致）。
 * @param serverKey @<root>/<server> 全名或裸名（策略键；与 policyAllows 同形态）。
 * @param tool 远端工具裸名。
 * @returns true = 拒绝执行（被禁用或策略 deny）。
 */
export function isToolDenied(
  disabledTools: DisabledToolsMap | undefined,
  policy: MiddlewarePolicy | undefined,
  serverKey: string,
  tool: string,
): boolean {
  const parsed = parseFullServerName(serverKey);
  if (parsed !== undefined) {
    const server = parsed.server;
    const set = disabledTools?.get(parsed.root)?.get(server);
    if (set !== undefined && set.size > 0 && set.has(tool)) return true;
    if (parsed.root !== MIDDLEWARE_GLOBAL_ROOT) {
      const globalSet = disabledTools?.get(MIDDLEWARE_GLOBAL_ROOT)?.get(server);
      if (globalSet !== undefined && globalSet.size > 0 && globalSet.has(tool)) return true;
    }
  }
  return !policyAllows(policy, serverKey, tool);
}

/** 策略拒绝原因（供 denialReason 提示）。 */
export function policyDenialReason(policy: MiddlewarePolicy | undefined, serverKey: string, tool: string): string | undefined {
  if (policyAllows(policy, serverKey, tool)) return undefined;
  const deny = policy?.denyTools?.[serverKey] ?? policy?.denyTools?.[bareServerName(serverKey)];
  if (deny !== undefined && deny.some((pattern) => globMatch(pattern, tool))) {
    return `ws_mcp_call: 工具 ${JSON.stringify(`${serverKey}/${tool}`)} 被 denyTools 策略拒绝`;
  }
  return `ws_mcp_call: 工具 ${JSON.stringify(`${serverKey}/${tool}`)} 不在 allowTools 白名单内，被策略拒绝`;
}

/** 工具级禁用的拒绝原因文案（三入口统一；P0-2 语义声明，#413 覆盖中间层工具）。 */
export function toolDisabledReason(serverKey: string, tool: string): string {
  return `ws_mcp_call: 工具 ${JSON.stringify(`${serverKey}/${tool}`)} 已被用户在「MCP」浮窗禁用；工具级禁用作用于 mcp-manager 管辖的全部 MCP 工具（mcp__ 前缀直呼与中间层 ws_mcp_* 一致生效），纪律裸名不受影响（如需恢复请到浮窗重新勾选）`;
}

