    sup.teardownGeneration(new Error("gone"));
    return { sup, log };
  }

  it("schedule=false → failed", () => {
    // 无 client：仅状态推进。
    const { sup } = bareFixture();
    sup.teardownGeneration(new Error("bare"), false);
