  });

  it("scope.watch 已注册（settings 装配面）", async () => {
    const { refs } = await applyWithSettingsLifecycle();
    expect(refs.watchCb).not.toBeNull();
  });

  // 哑断言清理（#664 阶段 8）：isUnloading 短路（unloading/disposed 态
